#include <iostream>
#include <vector>
#include <cmath>

using namespace std;

#define ll long long

const ll INF = 1LL << 60;

// Input
ll N, K;
vector<ll> h;

vector<ll> dp(100010, INF);

inline void chmin(ll& a, ll b) {
    a = (a > b) ? b : a;
}

inline ll abs_diff(ll a, ll b) {
    return a > b ? a - b : b - a;
}

int main() {
    cin >> N >> K;
    h.resize(N); // Efficient allocation

    for (ll i = 0; i < N; i++) cin >> h[i]; // Reads heights

    dp[0] = 0;

    for (int i = 0; i < N; i++) {
        // Using a sliding window to minimize dp[j] calculations.
        for (int j = i + 1; j <= min(i + K, N - 1); j++) {
            chmin(dp[j], dp[i] + abs_diff(h[i], h[j]));
        }
    }

    cout << dp[N - 1] << endl;
}

